# -*- coding: utf-8 -*-
TITLE = "Paradoksy ekonomii – pojęcia i tezy z rozmów"
INTRO = "Pojęcia z książki G. Konat, T. Smuga (red.), „Paradoksy ekonomii. Rozmowy z polskimi ekonomistami”, PWN, Warszawa 2016 (lektura OWE). Opracowano na podstawie fragmentu udostępnionego na stronie prof. M. Goryni (spis treści i rozmowa z M. Gorynią, s. 175–191); pojęcia ogólne z książki są też w działach 1–8."
E = [
 ("Mezoekonomia", "Poziom analizy pośredni między mikro- a makroekonomią: branże (grupy firm wytwarzających takie same lub podobne produkty), sektory i ich regulacja. M. Gorynia traktuje otoczenie branżowe jako kontekst działania przedsiębiorstwa (s. 176–178).", {"k": ["mezoekonom", "mezo"]}),
 ("Branża (sektor)", "Grupa przedsiębiorstw wytwarzających takie same lub podobne wyroby lub usługi; podstawowa kategoria mezoekonomii i analizy konkurencji (np. pięć sił Portera).", {"k": ["branż"]}),
 ("Neoliberalizm", "Nurt myśli i polityki gospodarczej akcentujący rynek, prywatną własność, deregulację i ograniczoną rolę państwa. W rozmowie M. Gorynia odrzuca tezę o dominacji neoliberalizmu w polskiej ekonomii i jego pejoratywne rozumienie – rozumie go jako „nowoczesne podejście do roli państwa i polityki gospodarczej” (s. 181).", {"k": ["neoliberal"]}),
 ("Eklektyzm (racjonalny, refleksyjny)", "Świadome łączenie elementów różnych szkół ekonomii, dobieranych do przedmiotu badań, zamiast przynależności do jednej szkoły – tak M. Gorynia określa własną postawę (s. 181).", {"k": ["eklektyzm", "eklektyczn"]}),
 ("Neoklasyczna teoria przedsiębiorstwa (firmy)", "Najbardziej rozpowszechniona teoria firmy: przedsiębiorstwo jako podmiot maksymalizujący zysk przy danej technologii (funkcji produkcji) i pełnej racjonalności; przyjmuje założenia kontrfaktyczne (idealizacyjne). Pozostałe teorie firmy (behawioralne, menedżerskie, instytucjonalne) powstały jako jej krytyka lub rozwinięcie.", {"k": ["neoklasyczn teori", "teori firmy", "teoria firmy", "teorii firmy", "teoria przedsiębiorstwa"]}),
 ("Metoda idealizacji", "Sposób budowania teorii przez świadome przyjmowanie założeń upraszczających, niezgodnych z rzeczywistością (np. pełna informacja), a następnie ich stopniowe uchylanie (konkretyzacja) – koncepcja L. Nowaka z poznańskiej szkoły metodologicznej.", {"k": ["idealizacj"]}),
 ("Oportunizm (w nowej ekonomii instytucjonalnej)", "Dążenie do własnego interesu z użyciem podstępu (np. zatajanie informacji, łamanie umów) – obok ograniczonej racjonalności podstawowe założenie behawioralne teorii kosztów transakcyjnych O. Williamsona.", {"k": ["oportunizm", "oportunistyczn"]}),
 ("Dobra społecznie pożądane (merit goods)", "Dobra, których konsumpcję państwo uznaje za pożądaną i wspiera niezależnie od preferencji jednostek (np. edukacja, ochrona zdrowia, kultura) – pojęcie R. Musgrave’a. Przeciwieństwo: dobra społecznie niepożądane (demerit goods – np. alkohol, tytoń).", {"k": ["merit goods", "społecznie pożądan", "demerit"]}),
 ("Granice prywatyzacji", "Zakres, w jakim własność państwową można przekazać w ręce prywatne; poza nim pozostają m.in. zasoby naturalne (lasy, wody, kopaliny), dobra publiczne i dobra społecznie pożądane, za które państwo odpowiada jako „strażnik dobra wspólnego” (s. 182).", {"k": ["granic prywatyzacji", "granice prywatyzacji"]}),
 ("Rola państwa w gospodarce", "Państwo tworzy ramy gospodarowania: prawo, porządek publiczny, regulacje, politykę pieniężną i podatkową; spór dotyczy zakresu interwencji (od państwa minimalnego – „nocnego stróża” – po państwo opiekuńcze i interwencjonistyczne). Teza z rozmowy: rola państwa „nie powinna być mniejsza, tylko inna” (s. 182).", {"k": ["roli państwa", "rola państwa", "interwencjonizm"]}),
 ("Picking the winners", "„Wybieranie zwycięzców” – polityka, w której państwo wskazuje branże lub firmy-faworytów i wspiera je finansowo (pomoc publiczna). Krytycy (np. M. Gorynia, s. 184) wskazują, że państwo nie potrafi racjonalnie typować przyszłych liderów.", {"k": ["picking", "faworyt"]}),
 ("Polityka przemysłowa – horyzontalna i sektorowa", "Sektorowa (selektywna, wertykalna) wspiera wybrane branże; horyzontalna tworzy ogólne warunki rozwoju dla wszystkich firm: prywatyzacja, zachęty do oszczędności i inwestycji, wspieranie innowacyjności, badania i informacja o trendach technologicznych i popytowych.", {"k": ["polityk przemysłow", "polityka przemysłowa", "polityki przemysłowej", "horyzontaln"]}),
 ("Ekonomia przemysłowa (Industrial Organization)", "Dział ekonomii badający struktury rynków, zachowania firm i ich wyniki; klasyczny paradygmat struktura–zachowanie–wyniki (SCP) – J. Bain, R. Caves; z tego nurtu wyrosła teoria strategii konkurencyjnej M. Portera.", {"k": ["industrial organization", "ekonomia przemysłowa", "ekonomii przemysłowej", "struktura–zachowanie", "scp", "bain", "caves"]}),
 ("Biznes międzynarodowy i paradygmat eklektyczny (OLI)", "Biznes międzynarodowy bada działalność firm za granicą. Paradygmat eklektyczny J. Dunninga wyjaśnia bezpośrednie inwestycje zagraniczne trzema przewagami: własnościową (Ownership), lokalizacyjną (Location) i internalizacji (Internalisation); P. Buckley – teoria internalizacji.", {"k": ["biznes międzynarodow", "biznesu międzynarodow", "eklektyczn", "oli", "dunning", "buckley"]}),
 ("Inwestycje zagraniczne wychodzące (ekspansja zagraniczna polskich firm)", "Bezpośrednie inwestycje polskich przedsiębiorstw za granicą (zakup lub budowa filii) – rosnące zjawisko po 2004 r., przedmiot badań M. Goryni nad strategiami zagranicznej ekspansji przedsiębiorstw.", {"k": ["inwestycj wychodząc", "inwestycje wychodzące", "ekspansj zagraniczn", "ekspansji zagranicznej"]}),
 ("Konkurencyjność międzynarodowa przedsiębiorstwa i luka konkurencyjna", "Zdolność firmy do utrzymania i poprawy pozycji na rynkach międzynarodowych (potencjał konkurencyjny → strategia → pozycja konkurencyjna). Luka konkurencyjna – dystans dzielący przedsiębiorstwa krajowe od konkurentów zagranicznych (badania nad wejściem Polski do UE).", {"k": ["konkurencyjnoś międzynarodow", "konkurencyjność międzynarodowa", "luk konkurencyjn", "luka konkurencyjna", "potencjał konkurencyjn"]}),
 ("Monopol handlu zagranicznego", "Rozwiązanie instytucjonalne gospodarki socjalistycznej: prawo prowadzenia handlu z zagranicą przysługiwało wyłącznie wyspecjalizowanym przedsiębiorstwom państwowym (centralom handlu zagranicznego); zniesione w ramach reform pod koniec lat 80.", {"k": ["monopol handlu zagranicznego", "centrale handlu"]}),
 ("Ekonomia pozytywna a postulatywna (normatywna) – spór", "Gorynia krytykuje „ekonomię postulatywną” – formułowanie zaleceń bez rzetelnej diagnozy empirycznej; podkreśla, że ekonomia całkowicie wolna od sądów wartościujących jest niemożliwa, ale nie może też odrywać się od empirii (s. 177, 190).", {"k": ["postulatywn", "sądów wartościując"]}),
 ("Instrumentalizm (M. Friedman)", "Stanowisko metodologiczne M. Friedmana („The Methodology of Positive Economics”, 1953): realizm założeń teorii nie jest istotny – jedynym testem teorii jest trafność jej przewidywań. Krytycy wskazują teorie o dużej mocy wyjaśniającej, a małej prognostycznej (np. teoria ewolucji – M. Blaug).", {"k": ["instrumentaliz"]}),
 ("Paradygmat (w nauce)", "Zestaw podstawowych pytań, założeń i metod uznawanych w danej dziedzinie za obowiązujące (T. Kuhn); w ekonomii zmieniają go m.in. wielkie wydarzenia – Wielki Kryzys 1929–1933 dał początek keynesizmowi, kryzys 2008 r. i transformacja ustrojowa zmieniły pytania badawcze.", {"k": ["paradygmat"]}),
 ("Ekonomiczna teoria demokracji", "Teoria A. Downsa (1957) stosująca założenie racjonalności do polityki: partie maksymalizują liczbę głosów, a wyborcy wybierają programy dające im największe korzyści (np. obietnice redystrybucji od bogatszych do biedniejszych); zalążek teorii wyboru publicznego.", {"k": ["teori demokracji", "teoria demokracji", "downs"]}),
 ("Teoria wyboru publicznego (public choice)", "Zastosowanie narzędzi ekonomii do analizy decyzji politycznych: polityków, biurokratów i grup interesu (J. Buchanan – Nobel 1986, G. Tullock); pojęcia: zawodność państwa, pogoń za rentą, cykl polityczny.", {"k": ["wyboru publiczn", "public choice", "grup interesu", "zawodnoś państwa", "buchanan"]}),
 ("Matematyzacja ekonomii – spór", "Krytyka (przytaczana za M. Friedmanem), że ekonomia staje się „tajemną gałęzią matematyki”; Gorynia uznaje nurt formalnego modelowania za ważny, ale nie dominujący – obok rozwijają się nurty jakościowe i interdyscyplinarne (s. 189).", {"k": ["gałęzią matematyki", "matematyz"]}),
 ("Szkoły myśli ekonomicznej w polskiej ekonomii akademickiej", "Temat podsumowujący książkę (rozdział s. 507): rozmówcy przypisują się do różnych nurtów – keynesizm i postkeynesizm (Kalecki, Łaski), neoliberalizm, ekonomia instytucjonalna, ekonomia ewolucyjna, szkoła austriacka; wielu deklaruje eklektyzm.", {"k": ["szkoł myśli", "szkoły myśli", "szkół myśli"]}),
]
